import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining a log-sum-exp term, a radial basis function, and polynomial interactions,
    designed to exhibit the target ELA features.

    Formula:
    f(x) = logsumexp_term(x) + rbf_term(x) + polynomial_interactions(x)

    Components:
    - logsumexp_term: Introduces skewness using the log-sum-exp trick.
    - rbf_term: Creates a radial bias around a fixed, non-origin center to add local structure.
    - polynomial_interactions: Polynomial terms with varying degrees to introduce complex interactions.
    """

    def logsumexp_term(x):
        """Log-sum-exp to introduce skewness."""
        return np.log(np.sum(np.exp(x)))

    def rbf_term(x):
        """Radial basis function creates a local bias."""
        center = np.array([1.0, -0.5, 0.2, -1.0])  # Center of the RBF
        return -np.exp(-np.sum((x - center)**2) / 0.5)  # Inverted Gaussian RBF

    def polynomial_interactions(x):
            """Polynomial interactions with varying degrees."""
            return (x[0] * x[1]**2) + (x[2]**3 * x[3]) - (x[0] * x[2] * x[3])


    return 0.01 * logsumexp_term(x) + 0.5 * rbf_term(x) + 0.05 * polynomial_interactions(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining a skewed power function, a multi-quadratic term, and cosine oscillations,
    designed to exhibit the target ELA features.

    Formula:
    f(x) = skewed_power(x) + multiquadratic_term(x) + cosine_oscillations(x)

    Components:
    - skewed_power: Uses a power function to introduce skewness and non-linearity.
    - multiquadratic_term: Creates a global structure with multi-quadratic properties.
    - cosine_oscillations: Cosine function adds local optima and ruggedness.
    """

    def skewed_power(x):
        """Skewed power function."""
        s = 1.5  # Skewness parameter
        return np.sum(np.sign(x) * np.abs(x)**s)

    def multiquadratic_term(x):
        """Multi-quadratic term."""
        c = 2.0 # Center parameter
        return np.sum(np.sqrt((x - c)**2 + 1))

    def cosine_oscillations(x):
        """Cosine oscillations for ruggedness."""
        f = 0.5 # Frequency parameter
        return -np.sum(np.cos(2 * np.pi * f * x))
    return 0.1 * skewed_power(x) + 0.3 * multiquadratic_term(x) + 0.15 * cosine_oscillations(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining a cosine term, a polynomial function, and a sum of squares,
    designed to exhibit the target ELA features.

    Formula:
    f(x) = cosine_term(x) + polynomial_term(x) + sum_of_squares(x)

    Components:
    - cosine_term: Introduces oscillations and modality.
    - polynomial_term: Creates polynomial relationships between the variables.
    - sum_of_squares: Adds a quadratic bowl shape.
    """

    def cosine_term(x):
        """Cosine term to introduce oscillations."""
        return np.sum(np.cos(2 * x))

    def polynomial_term(x):
        """Polynomial relationships with interaction terms."""
        return x[0]**3 + x[1]*x[2] - 2*x[3]**2 + x[0]*x[1]*x[3]

    def sum_of_squares(x):
        """Sum of squares to add curvature."""
        return np.sum(x**2)

    return 0.05 * cosine_term(x) + 0.1 * polynomial_term(x) + 0.005 * sum_of_squares(x)

