import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining a radial basis function (RBF) with polynomial modulation and an interaction term,
    designed to exhibit specific ELA features.

    Formula:
    f(x) = rbf_term(x) * polynomial_modulation(x) + interaction_term(x)

    Components:
    - rbf_term: Creates a radial bias around a fixed, non-origin center to add local structure.
    - polynomial_modulation: A polynomial modulating term with both individual and cross-product terms.
    - interaction_term: Includes a mix of second-order and third-order interactions to increase complexity and correlations.
    """

    def rbf_term(x):
        """Radial basis function creates a local bias."""
        center = np.array([1.0, -0.5, 0.2, -1.0]) # Center of the RBF
        return np.exp(-np.sum((x - center)**2) / 2) # Gaussian RBF

    def polynomial_modulation(x):
        """Polynomial term to modulate the RBF shape."""
        return (0.5 * x[0]**2 - 0.2 * x[1]**3 + 0.1 * x[2] * x[3] + 0.3*x[0])


    def interaction_term(x):
      """A mix of interaction terms to increase function complexity"""
      return 0.01*(x[0]*x[1] + x[1]*x[2]*x[3] + x[0]*x[3]**2)


    return 0.5 * rbf_term(x) * polynomial_modulation(x) +  interaction_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining a sum of exponentials, a polynomial term with interactions, and a product term.

    Formula:
    f(x) = sum_exp + poly_interact + product_term

    Components:
    - sum_exp: A sum of exponentials with linearly transformed input, introducing multimodality and skew.
    - poly_interact: Polynomial interactions of degree three, creating complex non-linear dependencies.
    - product_term: A product of sine functions to add oscillations.
    """

    def sum_exp(x):
        """Sum of exponentials term for multi-modality and skewness."""
        transformed_x = np.array([0.7 * x[0] + 0.3 * x[1],
                                  0.5 * x[1] - 0.5 * x[2],
                                  0.2 * x[2] + 0.8 * x[3],
                                  0.6 * x[3] - 0.4 * x[0]]) # linear transformation to further increase interactions
        return np.sum(np.exp(transformed_x))

    def poly_interact(x):
        """Polynomial interactions with degree three."""
        return (x[0] * x[1] * x[2]) - (x[1]**2 * x[3]) + (x[0] * x[2]**2) + (x[3]**3 * x[0])

    def product_term(x):
        """Product of Sine functions for oscillations."""
        return np.prod(np.sin(x))

    return 0.006 * sum_exp(x) + 0.001 * poly_interact(x) + 0.004 * product_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining an inverse multi-quadratic term,
    a product of sines term, and a sum of absolute values term, designed to exhibit
    specific ELA features.

    Formula:
    f(x) = inv_multiquad(x) + prod_of_sines(x) + abs_sum(x)

    Components:
    - inv_multiquad: Inverse multiquadratic function providing a smooth, non-quadratic global structure.
    - prod_of_sines:  A product of sine functions to add oscillating, multimodal characteristics.
    - abs_sum: Sum of absolute values introduces non-differentiability and emphasizes specific regions.
    """
    def inv_multiquad(x):
        """Inverse multiquadratic function."""
        c = 1.0  # Shape parameter
        return -np.sum(1 / np.sqrt(1 + (x / c)**2))

    def prod_of_sines(x):
        """Product of sines function."""
        scaled_x = np.array([0.7 * x[0], 1.1 * x[1], 0.9 * x[2], 1.3 * x[3]]) # Different scaling
        return np.prod(np.sin(scaled_x))

    def abs_sum(x):
        """Sum of absolute values."""
        return 0.1 * np.sum(np.abs(x))


    return 0.07 * inv_multiquad(x) + 0.1 * prod_of_sines(x) + 0.005 * abs_sum(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function combining a skewed polynomial, trigonometric functions, and radial basis functions.

    Formula:
    f(x) = skewed_polynomial(x) + trigonometric_term(x) + rbf_network(x) * decay(x)

    Components:
    - skewed_polynomial: Creates a skewed fitness distribution with a mix of odd and even powers and cross products.
    - trigonometric_term: Provides non-linearity and oscillatory behavior, useful for ELA feature tuning.
    - rbf_network: Multiple radial basis functions centered at different points to create multiple basins of attraction.
    - decay: Decays the importance of RBF far from the origin. This encourages locality and prevents unboundedness.
    """

    def skewed_polynomial(x):
        """Skewed polynomial with mixed terms."""
        return (0.01 * x[0]**3 * x[1] + 0.02 * x[1]**4 - 0.015 * x[2] * x[3]**2 + 0.005 * x[0] * x[2] * x[3])

    def trigonometric_term(x):
        """Trigonometric term for introducing non-linearity."""
        return 0.02 * np.sum(np.cos(x)) - 0.01 * np.sum(np.sin(2 * x))

    def rbf_network(x):
        """Network of RBFs centered at different locations."""
        centers = np.array([[1, -1, 0.5, -0.5],
                            [-0.5, 0.5, 1, -1],
                            [0.2, -0.2, -0.8, 0.8]])
        rbf_values = [np.exp(-np.sum((x - c)**2) / 0.5) for c in centers] # smaller values to constrain locality
        return np.sum(rbf_values)  # Sum of RBF activations

    def decay(x):
      """Function to lower importance of RBF tail contributions"""
      return np.exp(-np.sum(x**2) / 50)

    return skewed_polynomial(x) + trigonometric_term(x) + 0.01 * rbf_network(x) * decay(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 4-dimensional benchmark function constructed as a product of several components to achieve desired ELA characteristics.

    Formula:
    f(x) = gaussian_term(x) * cosine_term(x) * polynomial_term(x)

    Components:
    - gaussian_term: Creates a radial Gaussian shape, affecting the overall landscape.
    - cosine_term: Introduces oscillations and modulates the gaussian component. Influences fitness-distance correlation.
    - polynomial_term: Includes polynomial terms with interactions to introduce non-linearity and complexity.
    """

    def gaussian_term(x):
        """Gaussian term to shape the landscape"""
        center = np.array([0.5, -0.2, 0.1, -0.3])
        return np.exp(-np.sum((x - center)**2) / 2)

    def cosine_term(x):
        """Cosine term for oscillations and fitness-distance correlation modulation"""
        frequencies = np.array([1.1, 0.7, 1.3, 0.9])
        return np.cos(np.sum(frequencies * x))

    def polynomial_term(x):
        """Polynomial interactions to add complexity and non-linearity""
        """
        return (x[0] * x[1] + x[2] * x[3] + x[0]**2 - x[3]**3)

    return 0.9 * gaussian_term(x) * cosine_term(x) * (0.1 + polynomial_term(x))
